from decimal import Decimal

import pytest

from refproj.pricing import split_bill


def test_one_share_per_guest() -> None:
    assert len(split_bill(Decimal("12.34"), 7)) == 7


def test_shares_are_cents_not_fractions() -> None:
    shares = split_bill(Decimal("100.00"), 3)
    assert len(shares) == 3
    for share in shares:
        assert share == share.quantize(Decimal("0.01"))


def test_shares_add_up_to_the_bill_exactly() -> None:
    assert sum(split_bill(Decimal("10.00"), 3), start=Decimal("0")) == Decimal("10.00")


def test_no_two_shares_differ_by_more_than_one_cent() -> None:
    shares = split_bill(Decimal("100.00"), 7)
    assert max(shares) - min(shares) <= Decimal("0.01")


def test_larger_shares_come_first() -> None:
    shares = split_bill(Decimal("100.00"), 7)
    assert shares == sorted(shares, reverse=True)
    assert shares[0] > shares[-1]


def test_leftover_cents_go_to_the_first_guests_one_each() -> None:
    assert split_bill(Decimal("100.00"), 7) == [
        Decimal("14.29"),
        Decimal("14.29"),
        Decimal("14.29"),
        Decimal("14.29"),
        Decimal("14.28"),
        Decimal("14.28"),
        Decimal("14.28"),
    ]


def test_even_split_gives_equal_shares() -> None:
    assert split_bill(Decimal("100.00"), 4) == [Decimal("25.00")] * 4


def test_hundred_between_three() -> None:
    assert split_bill(Decimal("100.00"), 3) == [
        Decimal("33.34"),
        Decimal("33.33"),
        Decimal("33.33"),
    ]


def test_single_guest_pays_the_whole_bill() -> None:
    assert split_bill(Decimal("77.00"), 1) == [Decimal("77.00")]


def test_empty_bill_splits_into_zero_shares() -> None:
    assert split_bill(Decimal("0.00"), 2) == [Decimal("0.00"), Decimal("0.00")]


def test_bill_smaller_than_one_cent_each() -> None:
    assert split_bill(Decimal("0.01"), 2) == [Decimal("0.01"), Decimal("0.00")]


def test_largest_bill_and_most_guests_are_the_bounds() -> None:
    assert split_bill(Decimal("999999.99"), 100) == [Decimal("10000.00")] * 99 + [
        Decimal("9999.99")
    ]


@pytest.mark.parametrize("people", [0, -1, 101])
def test_people_outside_bounds_is_rejected(people: int) -> None:
    with pytest.raises(ValueError, match="people"):
        split_bill(Decimal("10.00"), people)


@pytest.mark.parametrize("amount", [Decimal("-0.01"), Decimal("1000000.00")])
def test_amount_outside_bounds_is_rejected(amount: Decimal) -> None:
    with pytest.raises(ValueError, match="amount"):
        split_bill(amount, 2)


def test_amount_with_a_fraction_of_a_cent_is_rejected() -> None:
    with pytest.raises(ValueError, match="amount"):
        split_bill(Decimal("10.005"), 2)

