def test_shelf_value_is_rounded_to_cents() -> None:
    value = shelf_value(StockItem(sku="T-3", unit_price=Decimal("0.333"), on_hand=3))
    assert value == Decimal("1.00")
    assert value.as_tuple().exponent == -2


def test_shelf_value_does_not_change_the_item() -> None:
    item = StockItem(sku="W-1", unit_price=Decimal("2.50"), on_hand=4)
    shelf_value(item)
    assert item == StockItem(sku="W-1", unit_price=Decimal("2.50"), on_hand=4)


def test_shelf_value_is_what_reserved_value_gives_for_on_hand(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    calls: list[tuple[StockItem, int]] = []

    def fake_reserved_value(item: StockItem, quantity: int) -> Decimal:
        calls.append((item, quantity))
        return Decimal("123.45")

    monkeypatch.setattr(inventory, "reserved_value", fake_reserved_value)
    assert shelf_value(WIDGET) == Decimal("123.45")
    assert calls == [(WIDGET, 4)]
